CREATE TABLE IF NOT EXISTS api_access_requests (id TEXT PRIMARY KEY NOT NULL,ticket_id TEXT NOT NULL,user_id TEXT NOT NULL,merchant_id TEXT NOT NULL,app_type TEXT NOT NULL CHECK (app_type IN ('website','bot','app')),app_name TEXT NOT NULL,website_url TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),reviewed_by TEXT,reviewed_at INTEGER,review_note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,FOREIGN KEY(ticket_id) REFERENCES support_tickets(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(merchant_id) REFERENCES pay_merchants(id) ON DELETE RESTRICT,FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS idx_api_access_requests_ticket_status ON api_access_requests(ticket_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_api_access_requests_merchant_status ON api_access_requests(merchant_id,status,created_at DESC);